#!/bin/bash
# Steps 10-12: regenerate numbers, compile, clean PDF metadata, run every check, write
# packet/checklist.md with the command outputs as evidence. Usage: bash code/make_packet.sh
set -u
cd "$(dirname "$0")/.."
PY=../shared/.venv/bin/python
OUT=packet/checklist.md
mkdir -p packet
run() {  # $1 = label, rest = command; appends command + output to the checklist
  local label="$1"; shift
  { echo; echo "### $label"; echo '```'; echo "\$ $*"; "$@" 2>&1 | tail -40; echo "(exit ${PIPESTATUS[0]})"; echo '```'; } >> "$OUT"
}
cat > "$OUT" <<HDR
# P5 submission checklist — generated by code/make_packet.sh on $(date -u +%Y-%m-%dT%H:%MZ)
Every block below is real command output from this run.
HDR
run "Unit tests" $PY -m pytest -q code/tests
run "Release schema validation" $PY code/validate_release.py
run "Statistics -> results.json" $PY code/stats.py
run "Figures" $PY code/figures.py
run "Macros (R2)" $PY ../shared/scripts/make_macros.py .
run "Abstract text from results.json" $PY code/make_abstract.py
run "Compile (tectonic)" bash -c "cd paper && tectonic -X compile main.tex 2>&1 | grep -iE '^error|undefined|overfull|warning: .*citation' ; echo compiled"
run "Clean PDF metadata (Title, Author only)" $PY code/clean_pdf.py paper/main.pdf packet/paper.pdf
run "pdfinfo" pdfinfo packet/paper.pdf
run "Fonts embedded (pdffonts)" pdffonts packet/paper.pdf
run "Page limit 4 + 1 (page_check.sh)" bash ../shared/scripts/page_check.sh packet/paper.pdf 4 1
run "Placeholders still in PDF text" bash -c "pdftotext packet/paper.pdf - | grep -nE 'PENDING|TBD|TODO|XXX' || echo none"
run "Overlap with other papers (overlap_check.py, threshold 0.5)" $PY ../shared/scripts/overlap_check.py ..
run "Anonymity grep (single-anonymous track: author hits EXPECTED)" bash ../shared/scripts/anon_check.sh . artifact/iotsecfix-1.0.0
run "Secrets grep in code and release" bash -c "grep -rIlE 'ghp_[A-Za-z0-9]{20}|github_pat_|AKIA[0-9A-Z]{16}|BEGIN (RSA|OPENSSH) PRIVATE' code data/release artifact_src || echo none"
run "Artifact package" sh code/make_artifact.sh
run "Artifact self-test" bash -c "cd artifact/iotsecfix-1.0.0 && ../../$PY code/validate_release.py && ../../$PY -m pytest -q -p no:cacheprovider code/tests && rm -rf code/__pycache__ code/tests/__pycache__"
cp abstract_draft.txt packet/abstract.txt
echo "wrote $OUT"
